import json
import math
import sys

import air_quality.health as h


def make_plan():
    # 5 regions in actions order (layer, rank):
    # [region, layer, score, members, bounds, configs, neighbors]
    actions = [
        [0, 0, 2,   3, [[1, 2], [3, 4]], [10, 20], [1, 2]],
        [2, 0, 1.5, 1, [[1, 2], [3, 4]], [20],     [0]],
        [1, 1, 0,   4, [[1, 2], [3, 4]], [10],     [0]],
        [3, 1, 0,   2, [[1, 2], [3, 4]], [],       []],
        [4, 2, 0,   5, [[1, 2], [3, 4]], [20],     []],
    ]
    batches = [
        [0, [0, 2], [2, 4, 3.5]],
        [1, [1, 3], [4, 10, 3.5]],
        [2, [4],    [5, 15, 3.5]],
    ]
    mapping = [[10, [0, 1]], [20, [0, 2, 4]]]
    return {
        "thresholds": [1, 2],
        "minimums": [3, 4],
        "actions": actions,
        "batches": batches,
        "mapping": mapping,
    }


def run(done, failed, batch=2):
    calls = {"n": 0}
    plan = make_plan()

    def fake_plan(*a, **k):
        calls["n"] += 1
        return plan

    orig = h.alert_region_plan
    h.alert_region_plan = fake_plan
    try:
        result = h.alert_region_progress(
            "s", "z", "st", "th", "mn", done, failed, 10, batch,
        )
    finally:
        h.alert_region_plan = orig
    assert calls["n"] == 1
    return result, plan


def test_basic_partition():
    result, plan = run(done=[4, 0], failed=[1, 2])
    assert list(result.keys()) == [
        "thresholds", "minimums", "state", "batches", "layers", "configs"
    ]
    assert result["thresholds"] == [1, 2]
    assert result["minimums"] == [3, 4]
    assert result["state"] == [[0, 4], [2, 1], [3]]

    assert result["batches"] == [
        [0, [0], [2], [], [1, 3, 2.0]],
        [1, [], [1], [3], [1, 3, 2.0]],
        [2, [4], [], [], [2, 8, 2.0]],
    ]
    assert result["layers"] == [
        [0, [0], [2], []],
        [1, [], [1], [3]],
        [2, [4], [], []],
    ]
    assert result["configs"] == [
        [10, [0], [1], []],
        [20, [0, 4], [2], []],
    ]
    json.dumps(result)  # JSON-compatible


def test_empty_sequences_all_unlisted():
    result, _ = run(done=(), failed=())
    all_ids = [0, 2, 1, 3, 4]
    assert result["state"] == [[], [], list(all_ids)]
    assert result["batches"][0] == [0, [], [], [0, 2], [0, 0, 0.0]]
    assert result["batches"][-1] == [2, [], [], [4], [0, 0, 0.0]]
    assert result["layers"][0] == [0, [], [], [0, 2]]
    assert result["configs"][0] == [10, [], [], [0, 1]]
    assert result["configs"][1] == [20, [], [], [0, 2, 4]]


def test_deep_copy_and_no_mutation():
    result, plan = run(done=[0], failed=[2])
    plan["actions"][0][4][0][0] = 999
    plan["thresholds"][0] = 999
    plan["mapping"][0][1].append(999)
    assert result["thresholds"] == [1, 2]
    # configs regions kept independent of mutated mapping list
    assert result["configs"][0] == [10, [0], [], [1]]
    assert result["thresholds"] is not plan["thresholds"]


def test_type_errors():
    for bad in (None, "x", {1}, {1: 2}, 3):
        try:
            run(done=bad, failed=[])
        except TypeError:
            pass
        else:
            raise AssertionError(f"done={bad!r} should raise TypeError")
        try:
            run(done=[], failed=bad)
        except TypeError:
            pass
        else:
            raise AssertionError(f"failed={bad!r} should raise TypeError")

    for bad in (True, False, 1.0, 0.0, "1", None):
        try:
            run(done=[bad], failed=[])
        except TypeError:
            pass
        else:
            raise AssertionError(f"done element {bad!r} should raise TypeError")


def test_value_errors():
    for args in (
            dict(done=[0, 0], failed=[]),
            dict(done=[], failed=[2, 2]),
            dict(done=[5], failed=[]),
